import {generations,periods,generationFor,concepts,common,opacity,memory,classifyAnswer,demoParticipant} from './domain.mjs';
const $=s=>document.querySelector(s),svgNS='http://www.w3.org/2000/svg';
let participants=Array.from({length:20},(_,i)=>demoParticipant(i)),enabled=new Set(generations.map(g=>g.id)),selected=null,zoom=1,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,visible=[],links=[],drag=null;
const positions=new Map(),emptyDetails=$('#details').innerHTML;
function element(tag,attrs={}){const el=document.createElementNS(svgNS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el;}
function text(tag,value,cls){const el=document.createElement(tag);el.textContent=value;if(cls)el.className=cls;return el;}
function gen(p){return generations.find(g=>g.id===p.generation);}
generations.forEach(g=>{const label=document.createElement('label');label.className='filter-row';const input=document.createElement('input');input.type='checkbox';input.checked=true;input.addEventListener('change',()=>{input.checked?enabled.add(g.id):enabled.delete(g.id);render();});const dot=text('span','','dot');dot.style.background=g.color;const name=text('span',g.label);name.append(text('small',g.range));label.append(input,dot,name);$('#filters').append(label);});
$('#all').onclick=()=>{enabled=new Set(generations.map(g=>g.id));$('#filters').querySelectorAll('input').forEach(i=>i.checked=true);render();};
function render(){visible=participants.filter(p=>enabled.has(p.generation));if(selected&&!visible.some(p=>p.id===selected))closeDetail();$('#count').textContent=`${visible.length} / ${participants.length} memorias`;$('#empty').hidden=visible.length>0;$('#edges').replaceChildren();$('#nodes').replaceChildren();links=[];
const select=$('#participant-select');select.replaceChildren(new Option('Selecciona una memoria',''));visible.forEach((p,i)=>{select.add(new Option(`${p.id} · ${gen(p).label}`,p.id));if(!positions.has(p.id)){const angle=i*2.39996;positions.set(p.id,{x:450+Math.cos(angle)*(65+i*7),y:300+Math.sin(angle)*(65+i*6),vx:0,vy:0});}const g=gen(p),node=element('g',{class:'node',tabindex:0,role:'button','aria-label':`Abrir ${p.id}, ${g.label}`});node.dataset.id=p.id;node.append(element('circle',{r:g.radius+6,fill:g.color,opacity:.06}),element('circle',{r:g.radius,fill:g.color,stroke:g.color,'stroke-width':1}));if(g.sprite)node.append(element('image',{href:g.sprite,x:-g.radius,y:-g.radius,width:g.radius*2,height:g.radius*2,'pointer-events':'none'}));const label=element('text',{'text-anchor':'middle',y:g.radius+18});label.textContent=p.id;node.append(label);node.addEventListener('click',()=>{if(!node.moved)showDetail(p.id);});node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showDetail(p.id);}});node.addEventListener('pointerdown',e=>{node.moved=false;drag={id:p.id,startX:e.clientX,startY:e.clientY,node};node.setPointerCapture(e.pointerId);});node.addEventListener('pointermove',e=>{if(drag?.id!==p.id)return;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4)node.moved=true;const pt=$('#viewport').getScreenCTM().inverse(),point=new DOMPoint(e.clientX,e.clientY).matrixTransform(pt);Object.assign(positions.get(p.id),{x:Math.max(35,Math.min(865,point.x)),y:Math.max(55,Math.min(540,point.y)),vx:0,vy:0});paint();});node.addEventListener('pointerup',()=>drag=null);node.addEventListener('pointercancel',()=>drag=null);$('#nodes').append(node);});
for(let i=0;i<visible.length;i++)for(let j=i+1;j<visible.length;j++){const a=visible[i],b=visible[j],shared=common(a.keywords,b.keywords),line=element('line',{stroke:'#d7c39b','stroke-opacity':opacity(shared.length),'stroke-width':.65});$('#edges').append(line);links.push({a:a.id,b:b.id,count:shared.length,line});}paint();if(selected)showDetail(selected);}
function paint(){for(const l of links){const a=positions.get(l.a),b=positions.get(l.b);for(const [key,value] of Object.entries({x1:a.x,y1:a.y,x2:b.x,y2:b.y}))l.line.setAttribute(key,value);}$('#nodes').querySelectorAll('.node').forEach(n=>{const p=positions.get(n.dataset.id);n.setAttribute('transform',`translate(${p.x},${p.y})`);n.classList.toggle('selected',n.dataset.id===selected);});}
function tick(){if(!paused){for(const p of visible){const a=positions.get(p.id);a.vx+=(450-a.x)*.0009;a.vy+=(285-a.y)*.0009;}for(const l of links){const a=positions.get(l.a),b=positions.get(l.b),dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.hypot(dx,dy)),repel=850/(d*d),spring=(d-(240-l.count*13))*.00018,force=spring-repel;const fx=dx/d*force,fy=dy/d*force;a.vx+=fx;a.vy+=fy;b.vx-=fx;b.vy-=fy;}for(const p of visible){if(drag?.id===p.id)continue;const a=positions.get(p.id);a.vx*=.86;a.vy*=.86;a.x=Math.max(40,Math.min(860,a.x+a.vx));a.y=Math.max(60,Math.min(525,a.y+a.vy));}paint();}requestAnimationFrame(tick);}
function closeDetail(){selected=null;$('#details').innerHTML=emptyDetails;$('#participant-select').value='';paint();}
function showDetail(id){const p=visible.find(v=>v.id===id);if(!p)return;selected=id;$('#participant-select').value=id;const root=$('#details');root.replaceChildren();const info=document.createElement('div'),top=text('div','','detail-top');top.append(text('p','02 / UNA MEMORIA','eyebrow'));const close=text('button','×');close.setAttribute('aria-label','Cerrar ficha');close.onclick=closeDetail;top.append(close);info.append(top,text('h2',p.id),text('p',gen(p).label,'generation-tag'),text('p','Participante ficticio · demostración','small muted'));info.append(text('h3','Referentes culturales'));const chips=text('div','','chips');p.keywords.forEach(k=>chips.append(text('span',k,'chip')));info.append(chips,text('h3','Acontecimientos y cambios'));const events=document.createElement('ul');p.events.forEach(e=>events.append(text('li',e)));info.append(events,text('h3','Su cápsula cultural'));const capsule=document.createElement('ul');p.capsule.forEach(c=>capsule.append(text('li',c)));info.append(capsule);const panel=text('section','','memory-section');panel.append(text('h3','Relación de memoria estimada'));const result=memory(p.answers);if(result){for(const key of ['directa','parcial','mediada']){const row=text('div','','bar-label');row.append(text('span',`Memoria ${key}`),text('span',`≈${result[key]} %`));const bar=text('div','',`bar ${key}`);bar.setAttribute('role','meter');bar.setAttribute('aria-label',`Memoria ${key} estimada`);bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax','100');bar.setAttribute('aria-valuenow',result[key]);const fill=text('span','');fill.style.width=`${result[key]}%`;bar.append(fill);panel.append(row,bar);}}else panel.append(text('p','Estimación pendiente de revisión: hay respuestas insuficientes o mixtas.','muted'));panel.append(text('p','Estimación basada en tus respuestas sobre lo vivido y lo recordado. Cada periodo pesa un 25 %.','small muted'));periods.forEach((period,i)=>panel.append(text('div',`${period} · ${p.answers[i]}`,'period-detail')));root.append(info,panel);paint();}
$('#participant-select').onchange=e=>e.target.value?showDetail(e.target.value):closeDetail();
function setZoom(value){zoom=Math.max(.6,Math.min(2,value));$('#viewport').setAttribute('transform',`translate(${450*(1-zoom)},${300*(1-zoom)}) scale(${zoom})`);}$('#zoom-in').onclick=()=>setZoom(zoom+.2);$('#zoom-out').onclick=()=>setZoom(zoom-.2);$('#reset').onclick=()=>setZoom(1);$('#graph').addEventListener('wheel',e=>{e.preventDefault();setZoom(zoom+(e.deltaY<0?.1:-.1));},{passive:false});function pauseLabel(){$('#pause').textContent=paused?'▷':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Reanudar movimiento':'Pausar movimiento');}$('#pause').onclick=()=>{paused=!paused;pauseLabel();};pauseLabel();
periods.forEach((period,i)=>{const row=text('div','','period-row');row.append(text('strong',period));const lived=document.createElement('label');lived.append(document.createTextNode('¿La viviste?'));const ls=document.createElement('select');ls.name=`lived${i}`;ls.required=true;[['','Selecciona'],['si','Sí'],['no','No']].forEach(([v,l])=>ls.add(new Option(l,v)));lived.append(ls);const recall=document.createElement('label');recall.append(document.createTextNode('¿Cómo la recuerdas?'));const rs=document.createElement('select');rs.name=`recall${i}`;[['','Selecciona'],['claro','Con recuerdos propios claros'],['parcial','Con recuerdos parciales'],['no','No la recuerdo / no lo sé']].forEach(([v,l])=>rs.add(new Option(l,v)));rs.required=true;ls.onchange=()=>{rs.disabled=ls.value==='no';rs.required=!rs.disabled;};recall.append(rs);row.append(lived,recall);$('#period-fields').append(row);});
$('#add-form').elements.year.max=new Date().getFullYear();$('#open-add').onclick=()=>$('#add-dialog').showModal();$('#close-add').onclick=()=>$('#add-dialog').close();$('#add-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),g=generationFor(Number(form.get('year'))),keywords=concepts(String(form.get('keywords')).split(',')),capsule=String(form.get('capsule')).split(',').map(x=>x.trim()).filter(Boolean);if(!g||!keywords.length||keywords.length>12||!capsule.length){$('#form-error').textContent='Comprueba el año y escribe entre 1 y 12 referentes y al menos un elemento para la cápsula.';return;}const answers=periods.map((_,i)=>classifyAnswer(form.get(`lived${i}`),form.get(`recall${i}`)));const p={id:`R-${String(participants.length+1).padStart(3,'0')}`,generation:g.id,keywords,capsule,events:['Sin acontecimientos registrados en esta demostración'],answers,synthetic:true};participants.push(p);enabled.add(g.id);$('#filters').querySelectorAll('input').forEach((input,i)=>input.checked=enabled.has(generations[i].id));render();showDetail(p.id);$('#add-dialog').close();e.target.reset();e.target.querySelectorAll('select').forEach(s=>{s.disabled=false;s.required=true;});$('#form-error').textContent='';$('#announcement').textContent=`Memoria ${p.id} incorporada a la red.`;};
render();requestAnimationFrame(tick);
